class Solution {
    int ans = 0;
    std::pair<int, int> dfs(TreeNode* node) {
        if (!node) return {0, 0};
        auto [l_sum, l_cnt] = dfs(node->left);
        auto [r_sum, r_cnt] = dfs(node->right);
        int s = l_sum + r_sum + node->val;
        int c = l_cnt + r_cnt + 1;
        if (s / c == node->val) ++ans;
        return {s, c};
    }
public:
    int averageOfSubtree(TreeNode* root) {
        ans = 0;
        dfs(root);
        return ans;
    }
};

class Solution {
    private int ans = 0;
    public int averageOfSubtree(TreeNode root) {
        ans = 0;
        dfs(root);
        return ans;
    }
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] left = dfs(node.left);
        int[] right = dfs(node.right);
        int s = left[0] + right[0] + node.val;
        int c = left[1] + right[1] + 1;
        if (s / c == node.val) ans++;
        return new int[]{s, c};
    }
}

var averageOfSubtree = function(root) {
    let ans = 0;
    const dfs = (node) => {
        if (!node) return [0, 0];
        const [lSum, lCnt] = dfs(node.left);
        const [rSum, rCnt] = dfs(node.right);
        const s = lSum + rSum + node.val;
        const c = lCnt + rCnt + 1;
        if (Math.floor(s / c) === node.val) ans++;
        return [s, c];
    };
    dfs(root);
    return ans;
};
